  v = `Opcionális: Dönthetsz úgy, hogy meghívsz más fejlesztőket, hogy adják játékaikat a kötegedhez. A köteg tulajdonosaként te vagy a felelős a többi fejlesztővel való egyeztetésért. Valamint, tulajdonosként egyedül te tudod kiadni a köteget a Steam Áruházban. A meghívott felek kiválaszthatják, mely játékokat, illetve csomagokat szeretnék hozzáadni. Valahányszor csomag kerül hozzáadásra a köteghez, vagy megváltozik a kedvezményszázalék, minden együttműködőnek hozzá kell járulnia játéka köteghez adásához, mielőtt az kiadásra kerülhet.`,
