  Pa = `Fellebbezés elutasítása`,
  Fa = `Biztos vagy benne? Ez frissíteni fogja a(z) %1$s állapotát, és e-mailben értesíti a fellebbezőt a döntésünkről.`,
  Ia = `Az eseményoldalnak lehet egy vagy több olyan szakasza, amelyek csak kedvezményes játékokat engednek megjelenni. Lesz egy vagy több olyan szakasz is az eseményoldalon, amelyek elsődlegesen kedvezményes játékokat fognak kiemelni.`,
  La = `Regisztráció a(z) %1$s eseményre`,
  Ra = `Állapot: Részvételre nem jogosult`,
  za = `Állapot: Már nem jogosult, mert a játék megjelent`,
