  Ha = `Állapot: Regisztrálási fellebbezésed felülvizsgálatra vár`,
  Ua = `A kért feliratkozás (%1$s) nem létezik.`,
  Wa = `A feliratkozási esemény véget ért. Jelenleg nem lehet fellebbezni.`,
  Ga = `A játék (%1$s) már része az eseménynek (%2$s).`,
  Ka = `Menj az itt található regisztrációs oldalra.`,
  qa = `Felülvizsgáló csapatunk megállapította, hogy a(z) %1$s nem felel meg az esemény jogosultsági kritériumainak.`,
  Ja = `Az egyes hivatalos Steam tematikus vásárokra meghívott játékoknak egyértelműen meg kell felelniük az esemény általános témájának és jogosultsági kritériumainak. A jogosultságot a játékod áruházi oldalán alkalmazott címkék határozzák meg, valamint a játékmenet, ami abból látható, ahogy az áruházi oldaladon leírod és megjeleníted a játékod.`,
  Ya = `A meghívandó játékok listájának összeállításakor általában az alábbiaknak megfelelő játékokat keresünk:`,
  Xa = `<2>Kritikus fontosságú áruházi címkék</2>, amelyek a témát képviselik. A játékodhoz jelenleg beállított címkéket a <1>címkevarázslót</1> felkeresve tekintheted át.`,
  Za = `<1>Áruházi oldali leírás.</1> Megnézzük a játék előzetesét, képernyőmentéseit és leírását, hogy lássuk, a jellemzői alapján illik-e az esemény témájához.`,
  Qa = `Felülvizsgálati csapatunk eredetileg nem vette fontolóra a(z) %1$s játékot ehhez az eseményhez.`,
  $a = `Jogosultsági kritériumok`,
  eo = `Fellebbezés a(z) %1$s részvételéért`,
  to = `A(z) %1$s fellebbezését lezártuk`,
  no = `Kérj felülvizsgálatot a(z) %1$s számára`,
  ro = `Ha úgy véled, játékod egyértelműen megfelel minden fenti jogosultsági kritériumnak, az itt található fellebbezési eljárással értesíthetsz bennünket. Játékodat az áruházi oldala alapján fogjuk felülvizsgálni, ezért kérjük, tekintsd át azt – beleértve az előzeteseket, a képernyőmentéseket és a címkéket –, megbizonyosodva arról, hogy a játékod oly módon van bemutatva, ami egyértelműen illik a szóban forgó témához.`,
  io = `A felülvizsgálat után úgy gondoljuk, hogy a(z) %1$s nem illeszkedik az esemény témájához. Kérjük, figyeld az olyan jövőbeli eseményeket, amelyek jobban illeszkednek a játékod témájához, illetve játékmenetéhez.`,
  ao = `Fellebbezési folyamat elindítása`,
  oo = `Fellebbezésed beküldésre került`,
  so = `Fellebbezésed beküldésre került. E kérelmeket rendszeresen felülvizsgáljuk, és e-mailben fogunk értesíteni a fellebbezésed eredményéről.`,
  co = `A fellebbezési folyamat`,
  lo = `A kérelmeket rendszeresen felülvizsgáljuk a(z) %1$s eseményig és az alatt. E-mailben fogunk értesíteni a fellebbezésed eredményéről.`,
  uo = `Fellebbezés eredménye: elutasítva`,
  fo = `A csapatunk még egyszer megnézte a játékodat, és megállapította, hogy az nem illik a(z) %1$s eseményhez.`,
  po = `Egész évben vannak különleges eseménylehetőségek, ezért nézd meg a <1>közelgő események</1> listáját, vagy figyelj olyan tematikus eseményekre, amelyek jobban illenek a játékodhoz.`,
  mo = `További részletekért nézd meg a(z) %1$s.`,
  ho = `%1$s dokumentációt`,
  go = `Általános információkért a Steam tematikus vásáreseményekről, köztük a kiválasztási és meghívási folyamat részleteiről, a részvétel módjairól, az eseményláthatóságról és promócióról, a játékok láthatóságáról az eseményeken és a marketinganyagok engedélyeiről, kérjük, látogasd meg a <1>Steam tematikus vásáresemények szülődokumentációt</1>.`,
  _o = `Segítség kell?`,
  vo = `Ha úgy véled, hogy a játékod teljes mértékben megfelel ezen esemény jogosultsági kritériumainak, használhatod ezt a fellebbezési folyamatot, hogy tudasd velünk.`,
  yo = `Kérjük, tekintsd át az <1>áruházi oldaladat</1> és a <2>címkéidet</2>, észben tartva a jogosultsági kritériumokat. Kiegészítő információkat, mint a játékmenet-videók, demók vagy prezentációk, nem fogunk elfogadni. Csak a minden vásárló számára elérhető információk lesznek felhasználva e felülvizsgálati folyamatban.`,
  bo = `Árulj el többet a játékodról`,
  xo = `Kérjük, használd az alábbi űrlapot annak leírására, ami esetleg elkerülhette a figyelmünket játékod áruházi oldalának felülvizsgálatakor.`,
  So = `Fellebbezés beküldése`,
  Co = `Hiba történt a változtatás mentése közben. Kérjük, próbáld újra később.`,
  wo = `Fellebbezés nem lehetséges`,
  To = `A játékod kiadási dátuma az eseményt megelőzőre van beállítva. Csak %1$s után kiadott játékok jogosultak a részvételre.`,
  Eo = `Ha megváltoztak a kiadási terveid, és e dátum után fogod kiadni a játékodat, kérjük, frissítsd a kiadási dátumát a Steamworksben.`,
  Do = `Kérjük, további részletekért nézd meg a <1>Kiadási dátumok dokumentációt</1>.`,
  Oo = `Játékod kiadott állapotban van. Erre az eseményre nem fogadunk el kiadott játékokat.`,
  ko = `Az esemény már elkezdődött. Részvétellel kapcsolatos fellebbezéseket már nem fogadunk el.`,
  Ao = `Miért nem került be a játékod?`,
  jo = `A(z) %1$s el lett távolítva a(z) %2$s eseményből`,
  Mo = `A(z) %2$s a még meg nem jelent játékoknak szól. A(z) %1$s már elérhető a Steamen, ezért már nem felel meg a jogosultsági követelményeknek, és el lett távolítva az eseményből. Nincs további teendőd.`,
  No = `A játék %1$s dátummal el lett távolítva.`,
  Po = `A Steam Jövő Feszten nem szerepelnek modok. A(z) %1$s egy mod a Steamen, ezért el lett távolítva a(z) %2$s oldalról. Nincs további teendőd.`,
  Fo = `A játékod kiadási dátuma múltbeli időpontra van állítva, ezért nem volt automatikusan jogosult. Ha a kiadási dátumod múltbeli, de még mindig nem adtad ki a játékodat, fellebbezhetsz a részvételért az alábbi gombra kattintva.`,
