  bl = `Hogyan működik a meghívás?`,
  xl = `Ha a játékod meghívást kap a Napi ajánlatban részvételre, kapni fogsz egy e-mailt, és látni fogod a játékodat fentebb. Ettől a ponttól így működik a folyamat:`,
