  Cl = `A láthatóság a Steam kezdőoldalán és a vonatkozó címkeoldalakon 24 óráig tart, míg a kedvezmény 7–14 napig lesz aktív, a kedvezmény általad választott időtartamától függően. A kedvezmény az általad választott napon, csendes-óceáni idő szerint 10:00 órakor fog kezdődni.`,
  wl = `Amikor kiválasztasz egy szabad dátumot, be kell majd írnod egy engedményszázalékot, és kiválasztani, mely csomagokat kívánod bevonni a promócióba.`,
