  Vj = `Legkorábbi lehetséges kiadás: %1$s`,
  Hj = `A kiadás legkorábbi lehetséges dátuma két héttel azután lehet, hogy áruházi oldalad látható volt „Hamarosan jön” állapotban, vagy 21 nappal az első alkalmazáskredit-vásárlás után; amelyik későbbre esik. Kérjük, tervezz ennek megfelelően.`,
  Uj = `A kiadás legkorábbi lehetséges dátuma két héttel azután lehet, hogy áruházi oldalad látható volt „Hamarosan jön” állapotban. Kérjük, tervezz ennek megfelelően.`,
  Wj = `Állítsd be a dátumot, amelyen kiadni tervezed az alkalmazásodat a Steamen. Ha még nagyon messze állsz a kiadástól, egy gondos becslést adj meg. Ha el kell halasztanod a kiadást, legalább két héttel a korábban megadott előtt frissítened kell ezt a dátumot.`,
