  qj = `Tervezett kiadási dátumod jelenleg „%1$s”. Ha változtatnod kell ezen a dátumon, kérjük, <1>lépj kapcsolatba a Valve-vel itt</1> új kiadási dátumod okával, és hogy milyen dátumot szeretnél megadni. Legyél igen biztos benne, hogy az új dátumon sor fog kerülni a kiadásra.`,
  Jj = `MEGJEGYZÉS: Mivel „Hamarosan jön” oldalad élő, kiadási dátumod megváltoztatása áruházi oldalad azonnali közzétételét fogja okozni, hogy az tükrözze a frissített kiadási dátumot. Áruházi oldalad minden függő szerkesztése nyilvánossá fog válni.`,
  Yj = `MEGJEGYZÉS: A választható legkorábbi kiadási dátum „%1$s”. E dátum után bármikor megnyomhatod a kiadás gombot, attól függetlenül, mire van állítva tervezett kiadási dátumod.`,
