  mM = `Kívánságlista dokumentáció megnézése`,
  hM = `Amikor először adod ki a demódat, választhatóan beállíthatod, hogy a Steam értesítse a teljes játékodat kívánságlistázókat. Ez a lehetőség egyszer érhető el, a demód kiadása utáni első két héten belül. Kívánságlista-értesítés nem küldhető egy másik értesítéshez képest két héten belül, így ha két héten belül tervezed a játékod kiadását, lehet, hogy nem érdemes ezt tenni.`,
