  wM = `Az alapjátékodhoz és a demódhoz eltérő országkorlátozások vannak megadva. Mindkettőt vagy egy engedélyező vagy egy tiltó listára kell beállítani, nem pedig vegyesen. Alapjáték: %1$s. Demó: %2$s.`,
  TM = `Az alapjátékodhoz és a demódhoz eltérő országkorlátozások vannak megadva. A kívánságlistás e-maileket csak azoknak a vásárlóknak küldjük ki, akik mindkettőhöz hozzáférnek. Alapjáték: %1$s. Demó: %2$s.`,
