  PM = `<1><2>Demómegjelenésről csak egyszer küldhető e-mail.</2> Még akkor is csak egyszer küldhetsz kívánságlista-értesítő e-mailt, ha letiltod, majd újraaktiválod a demódat a jövőben.</1><1><2>A Steam két héten belül egynél többször nem küld e-mailt egy adott játékosnak.</2> Ha ezen e-mail kiküldése után két héten belül kiadod a teljes játékodat, a Steam nem fog kiadási értesítő e-mailt küldeni magáról a játékodról azoknak, akik most e-mailt kapnak. Tervezz eszerint.</1>`,
  FM = `E-mailek kiküldése`,
  IM = `Mégse`,
  LM = `Ha a játékod „Hamarosan jön”, használhatod ezt a beállítást annak kiválasztására, hogyan nézzen ki tervezett kiadási dátumod az Áruházban.`,
