  YM = `Varázsló indítása`,
  XM = `Azok alapján, amiket játékvezérlő-támogatásodról mondtál nekünk, a Steam a következő lebontást fogja mutatni a vásárlóknak:`,
  ZM = `Megjegyzés: a játékvezérlő-támogatás nem fog megfelelően megjelenni a Steam Könyvtárban, amíg az áruházi oldal nincs közzétéve.`,
