  hN = `Frissített oldalak megnézése`,
  gN = `Használd ezt csak a varázsló frissített oldalainak felkereséséhez.`,
  _N = `Hogy segítsünk a játékosoknak hozzáférhetőségi szükségleteiknek megfelelő játékokat találni, kérjük, válaszolj néhány kérdésre a játékodban levő kisegítő lehetőségekkel kapcsolatban.`,
  vN = `Az alapján, amit a kisegítő lehetőségeidről mondtál nekünk, a Steam a következő kinyitható listát fogja mutatni a vásárlóknak:`,
  yN = `Az alapján, amit mondtál nekünk, a játékod semmilyen, a Steam által támogatott kisegítő lehetőséggel sem rendelkezik.`,
  bN = `Kisegítő lehetőség varázsló`,
  xN = `Játékmenet`,
  SN = `A játékmeneti kisegítő lehetőségekkel kapcsolatos részletekért nézd át a <1>Kisegítő lehetőségek Steamworks dokumentációt</1>.`,
  CN = `A játékod ezek közül mely játékmeneti kisegítő lehetőségeket támogatja?`,
  wN = `Állítható nehézség`,
  TN = `A nehézségi beállítások lehetővé teszik a játékosoknak, hogy élményüket a képességeikhez és igényeikhez igazíthassák.`,
  EN = `Mentés bármikor`,
  DN = `A játékosok mind automatikusan, mind manuálisan menteni tudják a játékmenetet, és a mentés a játék bármely pontján végezhető. A játékosok ezt a címkét keresve tudják, hogy nem fognak jelentős haladást veszíteni.`,
  ON = `Felolvasott játékmenük`,
  kN = `A játékosok meg tudják hallgatni a hangosan felolvasott játékmenüket.`,
  AN = `Gyengén látó játékosok a felolvasásra támaszkodhatnak a menük használatához. Ha a játékod rendelkezik felolvasott menükkel, akkor vagy elérhetővé tetted a kezelőfelületi faszerkezetedet képernyőolvasóknak (például a <1>Microsoft UI-automatizálásán</1> keresztül), vagy az összes játékmenüdhöz és értesítésedhez biztosítottál felolvasást. Javaslatokért nézd át a <2>Kisegítő lehetőségek Steamworks dokumentációt</2>.`,
  jN = `Rendelkezik a játékod felolvasott játékmenükkel?`,
  MN = `Igen, a játékosok támaszkodhatnak felolvasásra a játékmenükben navigáláshoz.`,
