  PN = `Látás nélkül játszható`,
  FN = `A játékosok teljes mértékben játszani tudják a játékot anélkül, hogy látnák a képernyőt. A játékod vagy olyan játékmenet köré van tervezve, amely nem igényel látást (pl. hang), vagy a képernyőolvasók, illetve a narráció támogatása elég teljes az egész játék élvezetéhez.`,
  IN = `Egyes játékok játszhatók a képernyő látása nélkül. Például egy játék lehet teljesen hang alapú, vagy rendelkezhet elegendő támogatással a képernyőolvasókhoz, illetve narrációhoz ahhoz, hogy teljes élményt nyújtson látás nélkül.`,
  LN = `Játszható a játékod látás nélkül?`,
  RN = `Igen, a játékosok játszani tudnak anélkül, hogy látnák a képernyőt.`,
  zN = `Nem, a játékom nem játszható látás nélkül.`,
  BN = `Egyéni hangerőszabályzás`,
  VN = `A különböző fajta játékbeli hangok hangereje egymástól függetlenül állítható.`,
  HN = `Lehet, hogy a játékosoknak le kell halkítaniuk a zavaró hangokat, hogy azokra a hangokra tudjanak összpontosítani, amelyeket hallaniuk kell. Ha a játékodnak van egyéni hangerőszabályzása, a játékosok állítani tudják a különböző hangtípusok, mint például a zene, hanghatások, háttérhangok és karakterbeszéd egymáshoz viszonyított hangerejét. Egyetlen hangcsúszka nem felel meg ennek a feltételnek. Javaslatokért nézd át a <1>Kisegítő lehetőségek Steamworks dokumentációt</1>.`,
  UN = `Rendelkezik a játékod egyéni hangerőszabályzással?`,
  WN = `Igen, a játékosok szabályozni tudják a játékomban a különböző hangtípusok egymáshoz viszonyított hangerejét.`,
  GN = `Nem, a játékomnak nincs egyéni hangerőszabályzása.`,
  KN = `Irányított hang`,
  qN = `Lehet, hogy a játékosoknak hangjelzésekre kell támaszkodniuk a játékbeli objektumok elhelyezkedésének felismeréséhez. Ha a játékodnak sztereó hangja van, akkor a jobb és bal csatornával érzékelteti egy hang viszonylagos helyzetét. Ha a játékodnak térhatású hangja van, a játékosok bármely irányból jövő hang helyzetét meg tudják állapítani; fentről, lentről, hátulról vagy elölről.`,
  JN = `Milyen fajta irányított hangot támogat a játékod?`,
  YN = `Térhatású hang: irányított hang, pl. 3.1-es, 5.1-es, 7.1-es vagy hasonló technológiák.`,
  XN = `Sztereó hang: bal és jobb csatornák.`,
  ZN = `A játékomnak nincs irányított hangja.`,
  QN = `Sztereó hang`,
  $N = `A játékosok be tudják azonosítani, hogy a hangok mennyire balról vagy jobbról jönnek.`,
  eP = `Térhatású hang`,
  tP = `A játékosok bármilyen irányban be tudják azonosítani, hogy a hangok milyen messziről jönnek.`,
