  rP = `Válaszd ki, hogy a játékod a következő kisegítő látványfunkciók közül melyeket támogatja. A kisegítő látványfunkciókkal kapcsolatos részletekért nézd át a <1>Kisegítő lehetőségek Steamworks dokumentációt</1>.`,
  iP = `Játékod mely látvánnyal kapcsolatos kisegítő lehetőségeket támogatja ezek közül?`,
  aP = `Állítható szövegméret`,
  oP = `A játékosok állítani tudják a szövegek, például a játékbeli szöveg, menüszöveg, karakterpárbeszéd vagy feliratszöveg méretét.`,
  sP = `Feliratbeállítások`,
  cP = `A játékosoknak lehetőségük van testre szabni a feliratok megjelenítését az összes beszélt tartalomhoz és alapvető hanginformációkhoz. Látássérült játékosoknak az alap felirattámogatás lehet, hogy nem elegendő. Háttérátlátszóság-, szövegszín- és méretbeállítások biztosítása lehetővé tudja tenni a játékosoknak a feliratok nekik kényelmesre állítását.`,
  lP = `Alternatív színek`,
  uP = `A játékmenet nem támaszkodik a színekre a fontos információk kommunikálásához, vagy a játékosoknak lehetőségük van állítani az információk megkülönböztetéséhez használt színeket.`,
  dP = `Kamerakényelem`,
  fP = `A játékosoknak lehetőségük van állítani vagy kikapcsolni a kényelmetlen kameramozgást, például a képrázkódást, a kamerabillegést, illetve a mozgás elmosódását, vagy a játékodban nincsenek ilyen effektek.`,
  pP = `Kontrasztállítás`,
  mP = `A kontraszt állítható, például az előtér és a háttér színének módosításával, az előtér elemeinek kiemelésével, vagy a sötét, illetve világos mód bekapcsolásával.`,
  hP = `Bevitel`,
  gP = `Egyes játékosok olyan hozzáférhetőségi eszközökkel rendelkeznek, amelyek billentyűzetre, egérre vagy érintéses bevitelekre képeződnek le, vagy lehet, hogy a játékosok e bevitelek használatát részesítik előnyben. A beviteli kisegítő lehetőségekkel kapcsolatos részletekért nézd át a <1>Kisegítő lehetőségek Steamworks dokumentációt</1>.`,
  _P = `Játékod mely beviteli módokat támogatja ezek közül?`,
  vP = `Csak billentyűzet lehetőség`,
  yP = `A játékosok játszani tudják a játékot csak billentyűzettel, bármilyen további beviteli mechanizmus, például egér vagy játékvezérlő nélkül.`,
  bP = `Csak egér lehetőség`,
  xP = `A játékosok játszani tudják a játékot csak egérrel, bármilyen további beviteli mechanizmus, például billentyűzet vagy játékvezérlő nélkül.`,
  SP = `Csak érintéses lehetőség`,
  CP = `A játékosok játszani tudják a játékot csak érintéses vezérléssel, bármilyen további beviteli mechanizmus, például egér, billentyűzet vagy játékvezérlő nélkül.`,
  wP = `Időzített bevitelek`,
  TP = `Néhány játékos lehet, hogy nem képes semmiféle időzített bevitelt végrehajtani. Másoknak a pontosan időzített gombnyomás-sorozatok („QTE-k”) vagy a gombcsépelés lehet kényelmetlen vagy lehetetlen. Egyes játékok, például a vizuális regények vagy a körökre osztott játékok, nem igényelnek időzített beviteleket.`,
  EP = `Milyen fajta időzített bevitelt igényel a játékod?`,
