  AP = `Reakcióidő-feladatok (QTE) nélkül játszható`,
  jP = `A játékosok el tudják kerülni a pontosan időzített beviteleket (QTE) vagy a „gombcsépelést”.`,
  MP = `Saját tempódban játszható`,
  NP = `A játékosoknak annyi idejük van az egyes bevitelekre, amennyi csak szükséges, vagy a pontos időzítést igénylő bevitelek kikapcsolhatók vagy kihagyhatók.`,
  PP = `Szövegfelolvasás és beszédfelismerés`,
  FP = `Gyengén látó vagy hallássérült játékosoknak a játékokban levő szöveges vagy hangos csevegés társas élménye elérhetetlen lehet. A szövegfelolvasás a szöveges csevegés valós idejű hallgatását, a beszédfelismerés pedig a hangos csevegés valós idejű olvasását teszi lehetővé a játékosoknak. A szövegfelolvasás és beszédfelismerés funkciókkal kapcsolatos javaslatokért nézd át a <1>Kisegítő lehetőségek Steamworks dokumentációt</1>.`,
  IP = `A játékod ezek közül melyeket támogatja?`,
