  VP = `Összegzés`,
  HP = `Tekintsd át a választásaidat. Azok alapján, amiket a hozzáférhetőségi támogatásodról mondtál nekünk, ezek azok a kisegítő lehetőségek, amelyek meg fognak jelenni a játékodnál.`,
