  TF = `ÁLTALÁNOS BEVITEL támogatás`,
  EF = `Annak érdekében, hogy játékod játékvezérlő-támogatásának szintjét a lehető legjobb módon írhassuk le a játékosok számára, van egy gyors varázslónk néhány rövid kérdéssel. Kérjük, végezd el ezt a varázslót a legjobb tudásod szerint adott válaszokkal, hogy a Steam olyan játékokkal kapcsolhassa össze a játékosokat, amelyek jól működnek az ő eszközeikkel.`,
  DF = `Figyelj rá, hogy a játék által támogatott VR-eszközöket, beleértve a beviteli eszközöket is, a rendszerkövetelményekben kell leírni. Az itt leírt játékvezérlő-támogatásnak az asztali és a Nagy Kép mód támogatására kell vonatkoznia.`,
