  VF = `Nem, a játékom nem használja a Steam Bevitel API-t.`,
  HF = `Xbox-játékvezérlő-támogatás`,
  UF = `Ha a játékod rendelkezik teljes Xbox játékvezérlő-támogatással, akkor a játékosoknak képesnek kell lenniük elindítani, konfigurálni, játszani és leállítani a játékodat billentyűzethez való hozzáférés nélkül. Ahhoz, hogy őszintén kijelenthesd, a játékod rendelkezik Xbox játékvezérlő-támogatással, a játékodnak képesnek kell lennie a következőkre:`,
  WF = `A játékosnak mindent meg kell tudnia tenni a játékban csupán egy játékvezérlő használatával. Ebbe beletartozik a játékindítókon való átjutás, a játék játszása, a menükkel való interakció, a beállítások megváltoztatása és a játékból való kilépés is.`,
  GF = `A játékvezérlő leválasztása esetén a játéknak szünetelnie kell, kivéve, ha többjátékos.`,
  KF = `Bármilyen szövegbevitelt igénylő párbeszédablaknak meg kell nyitnia egy virtuális képernyő-billentyűzetet.`,
  qF = `Ha a játékod támogatja a helyi többjátékos módot, annak működnie kell több játékvezérlővel.`,
  JF = `Megfelel a játékod a fenti kritériumoknak a teljes Xbox-játékvezérlő-támogatáshoz?`,
  YF = `PlayStation játékvezérlő-támogatás`,
  XF = `Ha a játékod rendelkezik támogatással az alább felsorolt egy vagy több PlayStation játékvezérlő-modellhez, általában véve lehetségesnek kellene lennie, hogy ezen eszközökkel mindazt meg lehessen csinálni a játékban, amit az Xbox játékvezérlőkkel. Továbbá, a játékodnak meg kell tudnia tennie a következőket ahhoz, hogy PlayStation játékvezérlőket támogatónak legyen tekintve:`,
  ZF = `Jelenítse meg a megfelelő gombikonokat a képernyőn, amikor a felhasználót a játékvezérlő bizonyos gombjának megnyomására kéri.`,
  QF = `Legyen játszható a játék, kezelhetők a menük, megváltoztathatók a beállítások, és ki lehessen lépni.`,
  $F = `<1>USB/Bluetooth megjegyzés:</1> A PC-s PlayStation játékvezérlők esetében elég gyakori lehet, hogy az USB-s kapcsolat jól működik, de nem rendelkeznek ugyanolyan szintű támogatással Bluetoothon keresztül csatlakoztatva. Kérjük, erősítsd meg műszaki csapatoddal, hogy a játék valóban működik Bluetoothon keresztül, mielőtt alább kiválasztanád azt.`,
  eI = `<1>Igen</1>, a játékom ezeket támogatja: (válaszd ki az összes ide vonatkozót)`,
  tI = `Steam Bevitel API integráció`,
  nI = `Ha a játékodba teljesen integrálva van a Steam Bevitel API, akkor teljesen működnie kellene annak a több mint kétszáz játékvezérlő-modellnek szinte bármelyikével, amit egy játékos csatlakoztat, beleértve a jövőbeni modelleket. Hogy őszintén kijelenthesd, játékod rendelkezik ezzel a támogatással, legalább az alábbiakra képesnek kell lennie:`,
  rI = `Implementálj Steam Bevitel API műveleteket, és kérdezd le a hozzájuk tartozó műveleteredetet a megfelelő játékvezérlő-ikonok megjelenítéséhez a játékban a főbb játékvezérlő-modellekhez.`,
  iI = `Automatikusan szüneteltesse a játékot a játékvezérlő lecsatlakozásakor.`,
  aI = `A játékosnak képesnek kell lennie az általa használt játékvezérlő gombjainak újbóli kiosztására a Steam konfigurátor használatával.`,
  oI = `Ha kétségeid vannak, kérjük, kérdezd meg a műszaki csapatotoktól, használják-e a Steam Bevitel API-t.`,
  sI = `Teljesen kihasználja játékod a Steam Bevitel API-t a fent leírt módon?`,
