  eR = `Nem érhető el kapszula`,
  tR = `Nincs kifejezett választás. Az áruházi alapértelmezés az e játékhoz hivatkozott első franchise készítői oldala lesz (ha van).`,
  nR = `<Minden forrásból>`,
  rR = `Tartalmazza az összes készítői kezdőoldalról (fejlesztő/kiadó/franchise) az összes e játékhoz társított játékot. A manuális kiemelés lehetővé teszi konkrét készítői kezdőoldal kiválasztását kiemelésre. Az algoritmikus kiemelés az elsőként egyező franchise, fejlesztői és kiadói készítőt fogja előnyben részesíteni a megjelenítendő sorrendhez.`,
  iR = `DLC függőségek`,
  aR = `Szükség van e DLC működéséhez másik DLC-re? Válaszd ki a szükséges DLC-ket a szükségesként mutatáshoz. Az Áruház automatikusan meg fogja jeleníteni e függőséget az összes függő elem együtt megvásárlásának lehetőségével.`,
  oR = `Hozzáadás függőségként`,
  sR = `A függőségi viszony`,
  cR = `Szükséges`,
  lR = `A függő DLC követelmény a megfelelő működéshez és élményhez e DLC játszásakor.`,
  uR = `Ajánlott`,
  dR = `A függő DLC ajánlott e DLC teljes élvezetéhez.`,
  fR = `Áttekintés`,
  pR = `Kialakítás`,
  mR = `Kiadás`,
  hR = `Season Pass ütemtervleírás`,
  gR = `A Season Pass olyan megvásárolható DLC, amely jövőbeni tartalom kiadására tesz ígéretet az azokat megvásárlóknak vagy különálló DLC megjelenésekként, vagy az alapjátékon belül feloldott további tartalommal.`,
  _R = `E kötelezettségvállaláshoz a fejlesztőknek le kell írniuk a jelentős tartalomkiadások mindegyikének kiadási dátumát és a játékosoknak nyújtott tartalmaikat, alább beírva az egyes dátumokat és tartalmakat.`,
  vR = `Használd a fenti általános „DLC ismertetése” szakaszt a Season Pass általános leírásához, az alábbi tartalomkiadási dátumokat pedig a konkrét önálló tartalomkiadásokhoz.`,
  yR = `Amikor készen állsz tájékoztatni a játékosokat, hogy tartalmat adtál ki a Season Passban, használd az alábbi „Megjelölés kiadottként” lehetőséget, és kövesd az útmutatást. A részletekért, kérjük, tekintsd át a <1>Season Pass kiadási dokumentációt</1>.`,
  bR = `Új tartalomkiadás létrehozása`,
  xR = `A tartalomkiadás egy, a vásárló által értelmezhető konkrét teljesítés, várható teljesítési dátummal.`,
  SR = `Új tartalomkiadás létrehozása`,
  CR = `Kérjük, írd le Season Pass tartalomkiadásodat a játékosoknak.`,
  wR = `Belső leírás – mondd el a Valve-nek, mit szándékozol belefoglalni ebbe a mérföldkőbe.`,
  TR = `Vásárlóoldali lokalizált leírás.`,
  ER = `Vásárlóknak szánt név`,
  DR = `Dátummegjelenítés`,
  OR = `Tervezett kiadási dátum`,
  kR = `E dátummal tervezed kiadni ezt a tartalmat a játékosoknak. Ez a dátum lesz használva emlékeztetők beállításához a belső Steamworks műszerfaladon. Kérjük, a helyi időzónádat használd.`,
  AR = `Kiadás dátuma`,
  jR = `Mikor férhettek először hozzá a vásárlók ehhez a tartalomhoz?`,
  MR = `Korábban kiadottnak jelölés`,
  NR = `Ez egy korábban kiadott tartalom. Ha be van jelölve, lehetővé teszi múltbeli dátum beállítását. A közzétételkor nem fogja értesíteni a vásárlókat a megjelenésről. Nem lehet törölni a jelölést, ha a dátum múltbeli.`,
  PR = `A „korábban kiadott” jelölést nem lehet anélkül visszavonni, hogy a megjelenési dátumot előbb a jövőbe ne tennéd.`,
  FR = `Mentés és közzététel szükséges`,
  IR = `A dátumnak múltbelinek kell lennie, mivel e tartalomnak már kiadásra kellett kerülnie.`,
