  XR = `Kérjük, beszélj a játékosoknak itt e kiadás tartalmáról. Ez lehet olyan rövid vagy hosszú, amilyennek szeretnéd. Ha DLC-ként tervezed kiadni ezt a tartalmat, az itteni leírás lehet ugyanaz, mint a DLC oldalon.`,
