  jz = `Steam csapat – iparági találkozók felmérés`,
  Mz = `Szia, %1$s!%2$sHol szeretnél találkozni velünk?`,
  Nz = `Az alábbiakban felsoroljuk azokat az eseményeket, amelyeken a Steam csapat tagjai részt terveznek venni. Ha te is fontolgatod a részvételt, vagy ha a közelben laksz, és találkoznál velünk, kérjük, jelezd nekünk az alábbi űrlapon. Ezt utazási és rendezvénynaptárunk jobb megtervezésére fogjuk használni. Ha regisztrálsz egy eseményre, amelyen részt tervezünk venni, előnyben fogjuk részesíteni az eseményt felkeresőket, mielőtt szélesebb körben kiküldenénk a meghívóinkat.`,
